{
  "title": "Rescue in the Ruined City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined royal city.",
      "visual_description": "Wide shot at dusk: four figures on a windy ridge overlooking shattered spires and broken walls, tattered royal banners snapping in the distance.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 2,
      "caption": "The map reader traces the route into the city.",
      "visual_description": "Close on a weathered parchment map spread on a flat stone, ink lines marking gates and towers, lantern light on the map_reader's gloved hands.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 3,
      "caption": "The scout slips ahead to study the castle gates.",
      "visual_description": "The scout crouched behind rubble, peering through a cracked archway at massive iron-bound gates flanked by chipped lion statues.",
      "characters": ["scout"]
    },
    {
      "scene_number": 4,
      "caption": "Frightened townspeople warn the team away.",
      "visual_description": "A small cluster of ragged townspeople clutching bundles in a narrow alley, gesturing fearfully toward the cursed tower silhouette behind them.",
      "characters": ["map_reader", "magic_helper", "townspeople"]
    },
    {
      "scene_number": 5,
      "caption": "An armored patrol marches past the hiding team.",
      "visual_description": "Low angle from behind a broken cart: heavy boots and polished greaves of a patrol crossing a courtyard, the team pressed flat into shadow.",
      "characters": ["scout", "bridge_walker", "armored_patrol"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon ripple through the ruins.",
      "visual_description": "A cracked statue of a coiled dragon looms over a dry fountain, the magic_helper studying scorch marks on the stones with a faint glowing rune in their palm.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 7,
      "caption": "The team slips through a side gate beneath the banners.",
      "visual_description": "Tall ragged royal banners hanging from a stone arch; the scout pries open a narrow servant's door while the others wait in shadow.",
      "characters": ["scout", "map_reader", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 8,
      "caption": "A sleepy gate official almost notices them.",
      "visual_description": "A plump official slumped in a wooden booth, half-eaten apple in hand, eyes drooping as the team tiptoes past behind him.",
      "characters": ["sleepy_official", "scout", "bridge_walker"]
    },
    {
      "scene_number": 9,
      "caption": "The cursed tower casts a strange shadow across the path.",
      "visual_description": "A leaning black tower with windows leaking pale green light, its shadow falling unnaturally sideways across cobblestones where the team hesitates.",
      "characters": ["magic_helper", "map_reader", "bridge_walker"]
    },
    {
      "scene_number": 10,
      "caption": "The magic helper deciphers a sealed magic door.",
      "visual_description": "An ornate stone door covered in glowing runes; the magic_helper's hands trace patterns, light spilling onto their face as runes brighten one by one.",
      "characters": ["magic_helper", "scout"]
    },
    {
      "scene_number": 11,
      "caption": "Inside, they find the captive in a banner-draped chamber.",
      "visual_description": "A dim hall hung with faded royal banners; the captive sits bound to a carved chair, looking up as the team enters with lanterns raised.",
      "characters": ["scout", "magic_helper", "captive"]
    },
    {
      "scene_number": 12,
      "caption": "The scout cuts the captive free.",
      "visual_description": "Close on a small curved knife slicing rope, the captive's wrists falling open, relief breaking across their dusty face.",
      "characters": ["scout", "captive"]
    },
    {
      "scene_number": 13,
      "caption": "An armored patrol blocks the corridor on the way out.",
      "visual_description": "Three armored patrol soldiers filling a torchlit stone corridor, spears lowered, the team skidding to a halt in the foreground.",
      "characters": ["map_reader", "bridge_walker", "captive", "armored_patrol"]
    },
    {
      "scene_number": 14,
      "caption": "The magic helper distracts the patrol with conjured smoke.",
      "visual_description": "Billowing pale smoke filling the corridor, runes glowing in midair, soldiers coughing and swinging blindly as the team slips along the wall.",
      "characters": ["magic_helper", "captive", "armored_patrol"]
    },
    {
      "scene_number": 15,
      "caption": "Townspeople open a hidden passage to help them flee.",
      "visual_description": "A trapdoor under a rug in a humble kitchen; townspeople ushering the team down a ladder by candlelight.",
      "characters": ["townspeople", "captive", "scout", "map_reader"]
    },
    {
      "scene_number": 16,
      "caption": "A dragon's roar shakes loose stones above the bridge.",
      "visual_description": "The team bursts out of a ruined archway onto a long stone bridge over a black chasm; far overhead, a dark winged shape circles against storm clouds.",
      "characters": ["map_reader", "magic_helper", "bridge_walker", "captive", "dragon"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge walker carries the captive across the crumbling span.",
      "visual_description": "Mid-bridge: stones falling away into the chasm; the bridge_walker strides across an impossible gap with the captive on their back, the others sprinting behind.",
      "characters": ["bridge_walker", "captive", "scout", "magic_helper", "map_reader"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far cliff, the team looks back at the ruined city.",
      "visual_description": "Dawn light on a grassy cliff edge; the five figures stand together, the captive wrapped in a cloak, the broken city and distant dragon silhouette behind them.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker", "captive"]
    }
  ]
}

